// 审批卡状态 → 运行状态。
function drRunOf(ap) {
  const map = {
    pending: "waiting_approval",
    resolving: "waiting_approval",
    allowed: "queued",
    denied: "denied",
    cancelled: "cancelled",
    conflict: "conflict"
  };
  return {
    id: ap.runId,
    label: `${ap.title} · ${ap.target}`,
    state: map[ap.state],
    approvalId: ap.id
  };
}

